#!/usr/bin/env python3
"""Run a command under a pty, answer CPR queries, optionally send an answer."""
import os, pty, sys, select, time

cmd = sys.argv[1]
answer = sys.argv[2] if len(sys.argv) > 2 else None  # e.g. "y\n" / "n\n"
pid, fd = pty.fork()
if pid == 0:
    os.execvp("sh", ["sh", "-c", cmd])

out = b""
sent = False
deadline = time.time() + 20
while time.time() < deadline:
    r, _, _ = select.select([fd], [], [], 0.5)
    if r:
        try:
            data = os.read(fd, 4096)
        except OSError:
            break
        if not data:
            break
        out += data
        # respond to cursor-position-report request ESC[6n
        if b"\x1b[6n" in out:
            os.write(fd, b"\x1b[1;1R")
            out = out.replace(b"\x1b[6n", b"")  # only once per occurrence
        if answer and not sent and b"(y/N)" in out:
            os.write(fd, answer.encode())
            sent = True
    else:
        # idle: try sending answer if prompt seen
        if answer and not sent and b"(y/N)" in out:
            os.write(fd, answer.encode())
            sent = True
        # check child
        wpid, status = os.waitpid(pid, os.WNOHANG)
        if wpid == pid:
            break
# drain
try:
    while True:
        r, _, _ = select.select([fd], [], [], 0.2)
        if not r:
            break
        data = os.read(fd, 4096)
        if not data:
            break
        out += data
except OSError:
    pass
try:
    _, status = os.waitpid(pid, 0)
except ChildProcessError:
    status = 0
sys.stdout.buffer.write(out)
sys.stdout.buffer.flush()
print("\n[EXIT=%d]" % os.waitstatus_to_exitcode(status) if hasattr(os, "waitstatus_to_exitcode") else status)

